// 读取系统时钟，并将同一时刻转换为指定时区的中文时间。
export function readTime (timeZone: string) {
  try {
    const formatter = new Intl.DateTimeFormat('zh-CN', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
      timeZoneName: 'longOffset'
    })
    const now = new Date()
    return {
      ok: true as const,
      timeZone,
      capturedAt: now.toISOString(),
      localTime: formatter.format(now)
    }
  } catch (error) {
    if (error instanceof RangeError) {
      return {
        ok: false as const,
        timeZone,
        error: '无法识别这个时区，请提供有效的时区，例如 Asia/Tokyo。'
      }
    }
    throw error
  }
}

import { createTool } from '@mastra/core/tools'
import { z } from 'zod'
import { readTime } from './read-time.ts'

// 将时间函数包装为模型可请求的工具，并明确成功与失败的返回结构。
export const getCurrentTime = createTool({
  id: 'get-current-time',
  description: '读取指定时区的当前时间，返回取样时刻。适合回答“现在几点”。',
  inputSchema: z.object({
    timeZone: z.string().min(1).describe('时区标识，例如 Asia/Tokyo 或 Asia/Shanghai')
  }),
  outputSchema: z.discriminatedUnion('ok', [
    z.object({
      ok: z.literal(true),
      timeZone: z.string(),
      capturedAt: z.string(),
      localTime: z.string()
    }),
    z.object({
      ok: z.literal(false),
      timeZone: z.string(),
      error: z.string()
    })
  ]),
  execute: async ({ timeZone }) => readTime(timeZone)
})

